#!/usr/bin/env python3
"""Generate a bounded screenshot-analysis comparison from all measured trials."""
import argparse,hashlib,json,statistics,zipfile
from pathlib import Path
root=Path(__file__).resolve().parents[1];folder=root/'docs/workflows/2026-10-30-dashboard'
parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--check',action='store_true');args=parser.parse_args()
m=json.loads((folder/'manifest.json').read_text());fixtures=json.loads((folder/'fixtures.json').read_text());expected=[f['expected'] for f in fixtures]
assert len(fixtures)==60 and sum(map(len,expected))==1527
assert hashlib.sha256((folder/'screenshots.zip').read_bytes()).hexdigest()==m['corpus_sha256']
with zipfile.ZipFile(folder/'screenshots.zip') as z:
    assert len([n for n in z.namelist() if n.endswith('.png')])==60
    assert json.loads(z.read('fixtures.json'))==fixtures
assert len(m['runs'])==12
for round_id in range(1,7):assert [r['language'] for r in m['runs'] if r['round']==round_id]==(['robotjs','rust'] if round_id%2 else ['rust','robotjs'])
for row in m['runs']:
    run=json.loads((folder/row['file']).read_text());assert run['results']==expected and run['verified'] and run['targets']==1527 and run['screenshots']==60 and run['seconds']==row['seconds']
assert hashlib.sha256((folder/'dashboard.mp4').read_bytes()).hexdigest()==m['video_sha256']
for lang in ['robotjs','rust']:
    video=json.loads((folder/(lang+'-video.json')).read_text());assert video['complete']['results']==expected and video['complete']['verified']
    progress=[e for e in video['events'] if e['type']=='progress'];assert len(progress)==60
    assert [e['boxes'] for e in progress]==expected
stats={lang:{'median_ms':statistics.median([r['seconds']*1000 for r in m['runs'] if r['language']==lang]),'min_ms':min(r['seconds']*1000 for r in m['runs'] if r['language']==lang),'max_ms':max(r['seconds']*1000 for r in m['runs'] if r['language']==lang)} for lang in ['robotjs','rust']}
ratio=stats['robotjs']['median_ms']/stats['rust']['median_ms'];summary=json.dumps({'results':stats,'ratio':ratio,'screenshots':60,'targets':1527,'verified_runs':12},indent=2)+'\n';base='workflows/2026-10-30-dashboard/'
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rusty Robot: {ratio:.1f}× faster on screenshot target detection</title><meta name="description" content="Find 1,527 Ready badges across 60 dashboard screenshots. Same buffers, same grouping algorithm, six runs per library, and exact output checks."><link rel="stylesheet" href="site.css"><link rel="stylesheet" href="benchmark-explorer.css"></head><body><a class="skip" href="#main">Skip to results</a><nav class="nav" aria-label="Main navigation"><a class="brand" href="index.html"><img src="assets/robot.png" alt="" width="42" height="42">Rusty Robot</a><div class="nav-links"><a href="building-rusty-robot.html">How we built it</a><a href="api-benchmarks.html">All API results</a><a href="https://github.com/priyankark/rusty-robot">GitHub</a></div></nav><main class="wide" id="main"><div class="eyebrow">Screenshot analysis · Same inputs · Verified outputs</div><h1>Find 1,527 targets.<br>{ratio:.1f}× faster on this workload.</h1><p class="lede">Find every green “Ready” badge across 60 dashboard screenshots, then return its bounding box. Rusty Robot did the search and grouping in <strong>{stats['rust']['median_ms']:.1f} ms</strong>; RobotJS from Node took <strong>{stats['robotjs']['median_ms']:.1f} ms</strong>.</p><p>These are medians from six runs per library, in alternating order. All 12 runs returned the exact same 1,527 rectangles. The screenshots are generated test dashboards with 2,400 order cards—not a production customer workload.</p><div class="reading-guide"><p><strong>What is timed:</strong> search every image for the known badge color, collect matching pixel positions, and group them into rectangles. Both use their public find-all-color APIs and the same grouping steps.</p><p><strong>Outside the timer:</strong> screenshot capture, PNG decoding, disk reads, and a full warmup. Both receive identical, preloaded BGRA32 buffers. This measures image analysis, not complete desktop automation latency.</p></div><div class="explorer" role="figure" aria-label="Median time to analyze all 60 screenshots"><p class="chart-note">Complete 60-image batch · median milliseconds · common scale from zero · shorter is faster</p>'''
for lang,label,cls in [('robotjs','RobotJS','base'),('rust','Rust','rust')]:
    x=stats[lang];page+=f'<div class="bar-line"><span>{label}</span><div class="bar-track" aria-hidden="true"><div class="bar-fill {cls}" style="width:{x["median_ms"]/stats["robotjs"]["median_ms"]*100:.4f}%"></div></div><output>{x["median_ms"]:.1f} ms</output></div>'
page+=f'''</div><figure class="demo-card"><h2>Watch the detections appear</h2><p>RobotJS on the left, Rusty Robot on the right. Orange outlines show the rectangles returned by the real implementations.</p><video id="comparison" aria-label="RobotJS and Rusty Robot detecting Ready badges side by side" controls playsinline preload="none" poster="{base}dashboard.png" aria-describedby="video-caption"><source src="{base}dashboard.mp4" type="video/mp4"><a href="{base}dashboard.mp4">Download video</a></video><div class="links"><button type="button" id="normal">Replay at 1×</button><button type="button" id="slow">Inspect at ¼×</button></div><p id="playback" class="chart-note" aria-live="polite">Playback: original speed (1×).</p><figcaption id="video-caption">Separate illustrative takes recorded after the measurements, one library at a time, aligned at task start. Video times include progress reporting and recording overhead; they are not the medians above. The finished pane holds its final frame. <a href="{base}dashboard.mp4" download>Download the recording</a>.</figcaption></figure><h2>Every measured run is included</h2><div class="table-wrap" tabindex="0"><table><caption>Milliseconds for the same 60 screenshots. One warmup batch per process; no video capture during these measurements.</caption><thead><tr><th scope="col">Run</th><th scope="col">RobotJS</th><th scope="col">Rust</th><th scope="col">Output</th></tr></thead><tbody>'''
for n in range(1,7):
    rows={r['language']:r for r in m['runs'] if r['round']==n};page+=f'<tr><th scope="row">{n}</th><td>{rows["robotjs"]["seconds"]*1000:.1f}</td><td>{rows["rust"]["seconds"]*1000:.1f}</td><td>1,527 / 1,527 correct</td></tr>'
page+='''</tbody></table></div><h2>Why this favors Rust</h2><p>The find-all-color call returns many matching pixel positions. RobotJS creates JavaScript objects for those results; Rust returns a vector. The grouping loop also runs in JavaScript versus compiled Rust. Both perform the same algorithm on the same pixels. These timings include the public API’s result-allocation costs, which are part of this workflow.</p><p>This is color-based detection for a known UI, not OCR or a general vision model. It does not establish a universal Rust advantage or compare every possible custom JavaScript implementation. In our <a href="typing-comparison.html">controlled form-entry comparison</a>, RobotJS was faster with zero keyboard delay, and matched-rate typing was effectively tied.</p><details><summary>Reproduce it and inspect the evidence</summary><p>Apple M6, macOS 27.0, Node 24.22.0, Rust release build. Each process loads the same 60 images, validates a complete warmup, waits for the start signal, and processes the batch. Output checks run after the timer. Library order reverses each round. The 60 images are distinct pages of one generated dashboard design, so this is a narrow workload, not a diverse screenshot corpus.</p><p>The checked-in PNG archive and fixture metadata preserve the exact inputs and expected rectangles. The archived byte-buffer hashes allow decoded inputs to be checked before running. No typing delays or artificial sleeps enter the timed analysis.</p><div class="links"><a href="workflows/2026-10-30-dashboard/summary.json">Computed summary</a><a href="workflows/2026-10-30-dashboard/manifest.json">Runs, environment, and hashes</a><a href="workflows/2026-10-30-dashboard/screenshots.zip">Download all 60 screenshots</a><a href="https://github.com/priyankark/rusty-robot/tree/main/tools/benchmark-demo">Rust, Node, and fixture source</a></div></details><footer class="footer">Rusty Robot implements the library in Rust. RobotJS uses a Node.js API backed by C/C++. <a href="api-benchmarks.html">See the wider API comparison, including losses</a>.</footer></main><script>const video=document.getElementById('comparison');for(const [id,rate] of [['normal',1],['slow',0.25]])document.getElementById(id).addEventListener('click',()=>{video.playbackRate=rate;video.currentTime=0;document.getElementById('playback').textContent=rate===1?'Playback: original speed (1×).':'Playback: quarter speed (¼×), slowed 4× for inspection.';video.play().catch(()=>{document.getElementById('playback').textContent+=' Use the video play control to start.'})});</script></body></html>'''
for p,text in [(folder/'summary.json',summary),(root/'docs/demos.html',page)]:
    if args.check:assert p.read_text()==text,f'Run python3 scripts/dashboard-report.py ({p.name})'
    else:p.write_text(text)
print(summary)
